<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { authToken as token, isAdmin, setAuthToken, signOut, verifyAdminAccess } from '@/lib/auth'
import { api } from '@/lib/api'
import profilePlaceholder from '@/assets/profile-placeholder.svg'
type Tab = 'members'|'article'|'course'|'lesson'|'project'|'certificate'|'linkedin'|'member'|'student'|'admin'
type Member = { id:string; slug:string; name:string; headline:string|null; photoUrl:string|null }
type Course = { id:string; title:string }
type LinkedInConnection = { configured:boolean; connected:boolean; personUrn:string|null; expiresAt:string|null }
const router=useRouter(), activeTab=ref<Tab>('members'), members=ref<Member[]>([]), message=ref(''), error=ref(''), loading=ref(false), email=ref(''), password=ref('')
const newMember=ref({slug:'',name:'',headline:'',biography:'',photoUrl:'',email:'',password:''}), article=ref({title:'',content:'',tags:'',memberId:''}), course=ref({title:'',description:'',price:'0',thumbnailLink:'',memberIds:[] as string[]}), courses=ref<Course[]>([]), lesson=ref({courseId:'',title:'',videoLink:''}), project=ref({title:'',description:'',imagePath:'',projectUrl:'',displayOrder:'0',memberId:''}), certificate=ref({title:'',issuer:'',issuedDate:'',imagePath:'',displayOrder:'0',memberId:''}), account=ref({name:'',email:'',password:''})
const linkedIn=ref<LinkedInConnection|null>(null)
const tabs:{id:Tab;label:string;icon:string}[]=[{id:'members',label:'Members',icon:'◉'},{id:'article',label:'Article',icon:'✎'},{id:'course',label:'Course',icon:'▣'},{id:'lesson',label:'Lesson',icon:'▶'},{id:'project',label:'Project',icon:'◇'},{id:'certificate',label:'Certificate',icon:'★'},{id:'linkedin',label:'LinkedIn',icon:'in'},{id:'member',label:'Member account',icon:'♙'},{id:'student',label:'Student',icon:'◌'},{id:'admin',label:'Admin',icon:'⚙'}]
const activeTitle=computed(()=>tabs.find(t=>t.id===activeTab.value)?.label??'Admin')
async function loadDirectory(){members.value=await api<Member[]>('/members')}
async function loadCourses(){courses.value=await api<Course[]>('/courses')}
async function loadLinkedIn(){linkedIn.value=await api<LinkedInConnection>('/linkedin/connection')}
function feedback(){message.value='';error.value=''}
async function submit(action:()=>Promise<void>,success:string){feedback();loading.value=true;try{await action();message.value=success}catch(reason){error.value=reason instanceof Error?reason.message:'Something went wrong. Please try again.'}finally{loading.value=false}}
async function login(){await submit(async()=>{const auth=await api<{token:string;role:string}>('/auth/login',{method:'POST',body:JSON.stringify({email:email.value,password:password.value})});setAuthToken(auth.token,auth.role);if(!await verifyAdminAccess())throw new Error('This account is not an administrator.');await loadDirectory()},'Signed in.')}
async function createMember(){await submit(async()=>{const saved=await api<Member>('/members',{method:'POST',body:JSON.stringify(newMember.value)});newMember.value={slug:'',name:'',headline:'',biography:'',photoUrl:'',email:'',password:''};await loadDirectory();router.push(`/admin/members/${saved.slug}`)},'Member created.')}
async function createArticle(){await submit(async()=>{await api('/articles',{method:'POST',body:JSON.stringify({title:article.value.title,content:article.value.content,tags:article.value.tags.split(',').map(x=>x.trim()).filter(Boolean),memberId:article.value.memberId||null})});article.value={title:'',content:'',tags:'',memberId:''}},'Article published.')}
async function connectLinkedIn(){await submit(async()=>{const result=await api<{authorizationUrl:string}>('/linkedin/authorization-url',{method:'POST'});globalThis.location.assign(result.authorizationUrl)},'Opening LinkedIn…')}
async function createCourse(){await submit(async()=>{const saved=await api<Course>('/courses',{method:'POST',body:JSON.stringify({...course.value,price:Number(course.value.price),thumbnailLink:course.value.thumbnailLink||null})});course.value={title:'',description:'',price:'0',thumbnailLink:'',memberIds:[]};lesson.value.courseId=saved.id;await loadCourses()},'Course created. You can add its first lesson below.')}
async function createLesson(){await submit(async()=>{await api('/lessons',{method:'POST',body:JSON.stringify({...lesson.value,videoLink:lesson.value.videoLink||null})});lesson.value={courseId:lesson.value.courseId,title:'',videoLink:''}},'Lesson added to the course.')}
async function createProject(){await submit(async()=>{await api('/projects',{method:'POST',body:JSON.stringify({...project.value,description:project.value.description||null,imagePath:project.value.imagePath||null,displayOrder:Number(project.value.displayOrder),memberId:project.value.memberId||null})});project.value={title:'',description:'',imagePath:'',projectUrl:'',displayOrder:'0',memberId:''}},'Project added to the member profile.')}
async function createCertificate(){await submit(async()=>{await api('/certificates',{method:'POST',body:JSON.stringify({...certificate.value,issuedDate:certificate.value.issuedDate||null,displayOrder:Number(certificate.value.displayOrder),memberId:certificate.value.memberId||null})});certificate.value={title:'',issuer:'',issuedDate:'',imagePath:'',displayOrder:'0',memberId:''}},'Certificate added to the member profile.')}
async function createAccount(kind:'member'|'student'|'admin'){await submit(async()=>{await api(kind==='admin'?'/auth/admin':`/auth/${kind}s`,{method:'POST',body:JSON.stringify(account.value)});account.value={name:'',email:'',password:''};if(kind==='member')await loadDirectory()},`${kind.charAt(0).toUpperCase()+kind.slice(1)} account created.`)}
function scrollToNewMember(){ globalThis.document?.getElementById('new-member')?.scrollIntoView({ behavior: 'smooth' }) }
onMounted(async()=>{if(!token.value)return;try{if(!await verifyAdminAccess())throw new Error();await Promise.all([loadDirectory(),loadCourses(),loadLinkedIn()])}catch{signOut()}})
</script>
<template>
<main class="min-h-svh bg-canvas p-4 text-ink sm:p-6 lg:p-8"><section v-if="!isAdmin" class="mx-auto mt-[12vh] max-w-md rounded-3xl border border-ink/15 bg-white p-7 shadow-sm sm:p-10"><p class="eyebrow">BashMobarmeg Academy</p><h1 class="mt-4 font-serif text-5xl leading-none">Admin access</h1><p class="mt-4 text-muted-ink">Sign in with an administrator account to open the management workspace.</p><form class="mt-8 space-y-4" @submit.prevent="login"><input v-model="email" class="field" type="email" placeholder="Email" required><input v-model="password" class="field" type="password" placeholder="Password" required minlength="8"><p v-if="error" class="text-sm text-red-600">{{ error }}</p><button class="primary-button w-full" :disabled="loading">{{ loading?'Signing in…':'Sign in' }}</button></form></section>
<section v-else class="mx-auto grid max-w-350 gap-6 lg:grid-cols-[15rem_minmax(0,1fr)]"><aside class="admin-sidebar"><RouterLink to="/about" class="brand">BashMobarmeg<span>Academy</span></RouterLink><nav class="mt-10 grid gap-2" aria-label="Admin tools"><button v-for="tab in tabs" :key="tab.id" class="tab-button" :class="activeTab===tab.id&&'tab-active'" @click="activeTab=tab.id;feedback()"><span>{{ tab.icon }}</span>{{ tab.label }}</button></nav><button class="mt-auto text-left text-sm font-bold text-muted-ink hover:text-primary" @click="signOut">Sign out</button></aside><div class="min-w-0"><header class="flex flex-wrap items-end justify-between gap-4 border-b border-ink/15 pb-6"><div><p class="eyebrow">Management workspace</p><h1 class="mt-3 font-serif text-5xl tracking-[-.06em]">{{ activeTitle }}</h1></div><p class="max-w-sm text-sm leading-relaxed text-muted-ink">Create content and manage people without losing context.</p></header><p v-if="message" class="feedback success">{{ message }}</p><p v-if="error" class="feedback failure">{{ error }}</p>
<section v-if="activeTab==='members'" class="mt-8"><div class="flex flex-wrap items-center justify-between gap-4"><div><h2 class="font-serif text-3xl">Member directory</h2><p class="mt-2 text-sm text-muted-ink">Choose a profile to edit its picture, identity, experience, and profile content.</p></div><button class="primary-button" @click="scrollToNewMember">+ New member</button></div><div class="member-grid mt-8"><button v-for="member in members" :key="member.id" class="member-card" @click="router.push(`/admin/members/${member.slug}`)"><img :src="member.photoUrl||profilePlaceholder" :alt="member.name"><span class="member-card-copy"><b>{{ member.name }}</b><small>{{ member.headline||'Member' }}</small></span><span class="member-open">Edit profile →</span></button></div><form id="new-member" class="editor-card mt-10 max-w-3xl" @submit.prevent="createMember"><h2 class="font-serif text-3xl">Add a member</h2><p class="mt-2 text-sm text-muted-ink">Creates a user account and public profile at <code>/members/your-slug</code>.</p><div class="mt-6 grid gap-4 sm:grid-cols-2"><input v-model="newMember.name" class="field" placeholder="Full name" required><input v-model="newMember.slug" class="field" placeholder="URL slug, e.g. mohammed" required><input v-model="newMember.email" class="field" type="email" placeholder="Email address" required><input v-model="newMember.password" class="field" type="password" minlength="8" placeholder="Password (min 8 characters)" required><input v-model="newMember.headline" class="field sm:col-span-2" placeholder="Role or headline"><input v-model="newMember.photoUrl" class="field sm:col-span-2" placeholder="Photo URL (optional)"><textarea v-model="newMember.biography" class="field min-h-32 sm:col-span-2" placeholder="Short biography"></textarea></div><button class="primary-button mt-5" :disabled="loading">Create member</button></form></section>
<section v-else-if="activeTab==='article'" class="editor-card mt-8 max-w-4xl"><h2 class="font-serif text-3xl">Write an article</h2><p class="mt-2 text-sm text-muted-ink">Use Markdown: <code># Heading</code>, <code>## Subheading</code>, <code>&gt; Quote</code>, or <code>- List item</code>.</p><form class="mt-6 grid gap-4" @submit.prevent="createArticle"><input v-model="article.title" class="field" placeholder="Article title" required><select v-model="article.memberId" class="field"><option value="">Global article</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}’s profile</option></select><input v-model="article.tags" class="field" placeholder="Tags, separated by commas"><textarea v-model="article.content" class="field min-h-80" placeholder="# First heading&#10;&#10;Write a paragraph here.&#10;&#10;&gt; Add a quote." required></textarea><button class="primary-button justify-self-start" :disabled="loading">Publish article</button></form></section>
<section v-else-if="activeTab==='course'" class="editor-card mt-8 max-w-4xl"><h2 class="font-serif text-3xl">Create a course</h2><p class="mt-2 text-sm text-muted-ink">Assign one or more members to the course.</p><form class="mt-6 grid gap-4 sm:grid-cols-2" @submit.prevent="createCourse"><input v-model="course.title" class="field sm:col-span-2" placeholder="Course title" required><select v-model="course.memberIds" class="field sm:col-span-2" multiple required><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select><input v-model="course.price" class="field" type="number" min="0" step=".01" placeholder="Price" required><input v-model="course.thumbnailLink" class="field" placeholder="Thumbnail URL"><textarea v-model="course.description" class="field min-h-44 sm:col-span-2" placeholder="Course description" required></textarea><button class="primary-button justify-self-start" :disabled="loading">Create course</button></form></section>
<section v-else-if="activeTab==='lesson'" class="editor-card mt-8 max-w-4xl"><h2 class="font-serif text-3xl">Add a lesson</h2><p class="mt-2 text-sm text-muted-ink">Choose the course that should contain this lesson.</p><form class="mt-6 grid gap-4 sm:grid-cols-2" @submit.prevent="createLesson"><select v-model="lesson.courseId" class="field sm:col-span-2" required><option value="" disabled>Select course</option><option v-for="item in courses" :key="item.id" :value="item.id">{{ item.title }}</option></select><input v-model="lesson.title" class="field sm:col-span-2" placeholder="Lesson title" required><input v-model="lesson.videoLink" class="field sm:col-span-2" type="url" placeholder="Video URL (optional)"><button class="primary-button justify-self-start" :disabled="loading || !courses.length">Add lesson</button></form><p v-if="!courses.length" class="mt-4 text-sm text-muted-ink">Create a course before adding lessons.</p></section>
<section v-else-if="activeTab==='project'" class="editor-card mt-8 max-w-4xl"><h2 class="font-serif text-3xl">Add a project</h2><p class="mt-2 text-sm text-muted-ink">Projects only appear on the selected member’s public profile.</p><form class="mt-6 grid gap-4 sm:grid-cols-2" @submit.prevent="createProject"><select v-model="project.memberId" class="field sm:col-span-2" required><option value="" disabled>Select member</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select><input v-model="project.title" class="field sm:col-span-2" placeholder="Project title" required><input v-model="project.projectUrl" class="field" type="url" placeholder="Project URL" required><input v-model="project.imagePath" class="field" placeholder="Image URL (optional)"><input v-model="project.displayOrder" class="field" type="number" min="0" placeholder="Display order" required><textarea v-model="project.description" class="field min-h-36 sm:col-span-2" placeholder="Project description"></textarea><button class="primary-button justify-self-start" :disabled="loading">Add project</button></form></section>
<section v-else-if="activeTab==='certificate'" class="editor-card mt-8 max-w-4xl"><h2 class="font-serif text-3xl">Add a certificate</h2><p class="mt-2 text-sm text-muted-ink">Certificates only appear on the selected member’s public profile.</p><form class="mt-6 grid gap-4 sm:grid-cols-2" @submit.prevent="createCertificate"><select v-model="certificate.memberId" class="field sm:col-span-2" required><option value="" disabled>Select member</option><option v-for="m in members" :key="m.id" :value="m.id">{{ m.name }}</option></select><input v-model="certificate.title" class="field" placeholder="Certificate title" required><input v-model="certificate.issuer" class="field" placeholder="Issuer"><input v-model="certificate.issuedDate" class="field" type="date"><input v-model="certificate.displayOrder" class="field" type="number" min="0" placeholder="Display order" required><input v-model="certificate.imagePath" class="field sm:col-span-2" placeholder="Certificate image URL" required><button class="primary-button justify-self-start" :disabled="loading">Add certificate</button></form></section>
<section v-else-if="activeTab==='linkedin'" class="editor-card mt-8 max-w-2xl"><h2 class="font-serif text-3xl">LinkedIn publishing</h2><p class="mt-2 text-sm text-muted-ink">Every new article is shared automatically after your account is connected. Access tokens remain only in the server database.</p><div v-if="linkedIn?.connected" class="mt-6 rounded-xl bg-emerald-50 p-4 text-sm text-emerald-800"><b>Connected</b><p class="mt-1">{{ linkedIn.personUrn }}</p><p v-if="linkedIn.expiresAt" class="mt-1">Access expires {{ new Date(linkedIn.expiresAt).toLocaleString() }}.</p></div><div v-else class="mt-6 rounded-xl bg-amber-50 p-4 text-sm text-amber-800"><b>{{ linkedIn?.configured ? 'Not connected' : 'Configuration required' }}</b><p class="mt-1">{{ linkedIn?.configured ? 'Connect the LinkedIn account that should publish your articles.' : 'Set the LinkedIn client ID, client secret, redirect URI, and token encryption key on the server first.' }}</p></div><button class="primary-button mt-5" :disabled="loading || !linkedIn?.configured" @click="connectLinkedIn">Connect LinkedIn</button></section>
<section v-else class="editor-card mt-8 max-w-2xl"><h2 class="font-serif text-3xl">Create {{ activeTitle.toLowerCase() }} account</h2><p class="mt-2 text-sm text-muted-ink">Creates a secure account with the appropriate role.</p><form class="mt-6 space-y-4" @submit.prevent="createAccount(activeTab as 'member'|'student'|'admin')"><input v-model="account.name" class="field" placeholder="Full name" required><input v-model="account.email" class="field" type="email" placeholder="Email" required><input v-model="account.password" class="field" type="password" minlength="8" placeholder="Temporary password" required><button class="primary-button" :disabled="loading">Create {{ activeTitle.toLowerCase() }}</button></form></section>
</div></section></main>
</template>
<style scoped>
.eyebrow{font-size:.75rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--color-primary)}.admin-sidebar{display:flex;min-height:calc(100svh - 4rem);flex-direction:column;border:1px solid color-mix(in srgb,var(--color-ink) 14%,transparent);border-radius:1.5rem;background:white;padding:1.25rem;box-shadow:0 1px 3px rgb(16 32 51 / 8%)}.brand{font-family:'Cairo',sans-serif;font-size:1.3rem;font-weight:800;letter-spacing:-.05em}.brand span{color:var(--color-primary)}.tab-button{display:flex;align-items:center;gap:.75rem;border-radius:.8rem;padding:.8rem .9rem;text-align:left;font-size:.9rem;font-weight:700;color:var(--color-muted-ink);transition:.2s}.tab-button:hover{background:color-mix(in srgb,var(--color-primary) 8%,white);color:var(--color-ink)}.tab-button span{display:grid;width:1.25rem;place-items:center;font-size:1.1rem}.tab-active{background:var(--color-primary);color:#fff;box-shadow:0 8px 20px rgb(14 165 233 / 24%)}.field{width:100%;border:1px solid color-mix(in srgb,var(--color-ink) 18%,transparent);border-radius:.8rem;background:#fff;padding:.8rem 1rem;color:var(--color-ink);outline:none;transition:.2s}.field:focus{border-color:var(--color-primary);box-shadow:0 0 0 3px rgb(14 165 233 / 14%)}.primary-button{border-radius:.8rem;background:var(--color-primary);padding:.8rem 1rem;font-size:.9rem;font-weight:700;color:white;transition:.2s}.primary-button:hover{filter:brightness(.92)}.primary-button:disabled{opacity:.6}.feedback{margin-top:1.5rem;border-radius:.8rem;padding:.8rem 1rem;font-size:.9rem}.success{background:#ecfdf5;color:#047857}.failure{background:#fef2f2;color:#b91c1c}.editor-card{border:1px solid color-mix(in srgb,var(--color-ink) 14%,transparent);border-radius:1.5rem;background:white;padding:1.5rem;box-shadow:0 1px 3px rgb(16 32 51 / 8%)}.member-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(10rem,1fr));gap:1rem}.member-card{position:relative;min-height:14rem;overflow:hidden;border:1px solid color-mix(in srgb,var(--color-ink) 14%,transparent);border-radius:1.25rem;background:white;padding:1rem;text-align:center;box-shadow:0 1px 3px rgb(16 32 51 / 8%);transition:transform .28s ease,box-shadow .28s ease,border-color .28s ease}.member-card img{margin:auto;height:8rem;width:8rem;border-radius:9999px;object-fit:cover;box-shadow:0 8px 24px rgb(16 32 51 / 14%);transition:transform .28s ease}.member-card-copy{display:block;margin-top:.8rem}.member-card-copy b,.member-card-copy small{display:block}.member-card-copy small{margin-top:.2rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--color-muted-ink);font-size:.75rem}.member-open{position:absolute;right:0;bottom:0;left:0;transform:translateY(100%);background:rgb(16 32 51 / 90%);padding:.7rem;color:white;font-size:.75rem;font-weight:700;transition:transform .28s ease}.member-grid:has(.member-card:hover) .member-card:not(:hover){opacity:.58;transform:scale(.96)}.member-card:hover{z-index:1;transform:translateY(-8px) scale(1.06);border-color:var(--color-primary);box-shadow:0 22px 42px rgb(16 32 51 / 20%)}.member-card:hover img{transform:translateY(-3px) scale(1.04)}.member-card:hover .member-open{transform:translateY(0)}@media(max-width:1023px){.admin-sidebar{min-height:auto}.admin-sidebar nav{grid-template-columns:repeat(3,minmax(0,1fr))}.admin-sidebar .tab-button{justify-content:center}.admin-sidebar .tab-button span{display:none}.admin-sidebar>button:last-child{margin-top:1.5rem}}@media(max-width:520px){.admin-sidebar nav{grid-template-columns:repeat(2,minmax(0,1fr))}.member-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
